import{c as t,Q as a,j as n,m as e}from"./chunks/framework.DOi4mjdC.js";const C=JSON.parse('{"title":"HCCL Tiling使用说明","description":"","frontmatter":{},"headers":[{"level":1,"title":"HCCL Tiling使用说明","slug":"hccl-tiling使用说明"}],"relativePath":"api/SIMD-API/高阶API/HCCL通信类/HCCL-Tiling侧接口/HCCL-Tiling使用说明.md","filePath":"api/SIMD-API/高阶API/HCCL通信类/HCCL-Tiling侧接口/HCCL-Tiling使用说明.md"}'),l={name:"api/SIMD-API/高阶API/HCCL通信类/HCCL-Tiling侧接口/HCCL-Tiling使用说明.md"};function s(p,i,g,c,d,o){return a(),n("div",null,[...i[0]||(i[0]=[e(`<h1 id="hccl-tiling使用说明" tabindex="-1">HCCL Tiling使用说明 <a class="header-anchor" href="#hccl-tiling使用说明" aria-label="Permalink to &quot;HCCL Tiling使用说明&quot;">​</a></h1><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p>本章节详述通信算子必需的TilingData结构体。本章节提供了三个版本的TilingData，建议使用<a href="./TilingData结构体.html">TilingData结构体</a>，不推荐使用<a href="./v1版本TilingData（废弃）.html">v1版本TilingData（废弃）</a>和<a href="./v2版本TilingData（废弃）.html">v2版本TilingData（废弃）</a>。 对于<a href="./TilingData结构体.html">TilingData结构体</a>，在定义通算融合算子的Tiling结构体时，<a href="./TilingData结构体.html#table4835205712588">Mc2InitTiling</a>必须定义为算子Tiling结构体的第一个参数，<a href="./TilingData结构体.html#table678914014562">Mc2CcTiling</a>对于在算子Tiling结构体中被定义的位置没有要求。</p></div><p>Ascend C提供一组HCCL Tiling API，方便用户获取HCCL Kernel计算时所需的Tiling参数。您只需要传入通信的相关信息，调用API接口，即可获取通信相关的Tiling参数。</p><p>HCCL Tiling API获取Tiling参数的流程如下：</p><ol><li><p>创建一个<a href="./HCCL-Tiling构造函数.html">Mc2CcTilingConfig</a>类对象。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>const char *groupName = &quot;testGroup&quot;;</span></span>
<span class="line"><span>uint32_t opType = HCCL_CMD_REDUCE_SCATTER;</span></span>
<span class="line"><span>std::string algConfig = &quot;ReduceScatter=level0:fullmesh&quot;;</span></span>
<span class="line"><span>uint32_t reduceType = HCCL_REDUCE_SUM;</span></span>
<span class="line"><span>AscendC::Mc2CcTilingConfig mc2CcTilingConfig(groupName, opType, algConfig, reduceType);</span></span></code></pre></div></li><li><p>通过配置接口设置通信信息（可选）。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mc2CcTilingConfig.SetSkipLocalRankCopy(0);</span></span>
<span class="line"><span>mc2CcTilingConfig.SetSkipBufferWindowCopy(1);</span></span></code></pre></div><p>可调用的配置接口列于下表。</p><p><strong>表 1</strong> Mc2CcTilingConfig类对象的配置接口列表</p></li></ol><table tabindex="0"><thead><tr><th>接口</th><th>功能</th></tr></thead><tbody><tr><td>SetOpType</td><td>设置通信任务类型。</td></tr><tr><td>SetGroupName</td><td>设置通信任务所在的通信域。</td></tr><tr><td>SetAlgConfig</td><td>设置通信算法。</td></tr><tr><td>SetReduceType</td><td>设置Reduce操作类型。</td></tr><tr><td>SetStepSize</td><td>设置细粒度通信时，通信算法的步长。</td></tr><tr><td>SetSkipLocalRankCopy</td><td>设置本卡的通信算法的计算结果是否输出到recvBuf。</td></tr><tr><td>SetSkipBufferWindowCopy</td><td>设置通信算法获取输入数据的位置。</td></tr><tr><td>SetDebugMode</td><td>设置调测模式。</td></tr></tbody></table><ol start="3"><li><p>调用<a href="./GetTiling-100.html">GetTiling</a>接口，获取Tiling信息。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mc2CcTilingConfig.GetTiling(tiling-&gt;mc2InitTiling); // tiling为算子组装的TilingData结构体</span></span>
<span class="line"><span>mc2CcTilingConfig.GetTiling(tiling-&gt;reduceScatterTiling);</span></span></code></pre></div></li></ol>`,7)])])}const T=t(l,[["render",s]]);export{C as __pageData,T as default};
